import TesLogo1 from '@/assets/img/logo/tes1-logo1.png';
import TesLogo2 from '@/assets/img/logo/tes1-logo2.png';
import TesLogo3 from '@/assets/img/logo/tes1-logo3.png';
import TesLogo4 from '@/assets/img/logo/tes1-logo4.png';
import TesLogo5 from '@/assets/img/logo/tes1-logo5.png';
import headings from '@/assets/img/shapes/headding1-span.png';
import TesBigImg from '@/assets/img/testimonial/tes1-big-img.png';
import { Link } from 'gatsby';
import React, { useEffect, useRef, useState } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import { FaArrowLeft, FaArrowRight, FaStar } from 'react-icons/fa6';
import Slider from 'react-slick';

type testimonial1Type = {
  image: string;
};
type Testimonial2Type = {
  id: number;
  name: string;
  role: string;
  company: string;
  message: string;
  image: string;
};

const testimonial1: testimonial1Type[] = [
  { image: TesLogo1 },
  { image: TesLogo2 },
  { image: TesLogo3 },
  { image: TesLogo4 },
  { image: TesLogo5 },
  { image: TesLogo1 },
  { image: TesLogo2 },
  { image: TesLogo3 },
  { image: TesLogo4 },
  { image: TesLogo5 },
];

const testimonials: Testimonial2Type[] = Array.from({ length: 10 }, (_, i) => ({
  id: i + 1,
  name: 'Oliver Grioud',
  role: 'CEO',
  company: 'Lava Ltd',
  message: `“The team at eSoft not only delivered what was promised but also provided 
            valuable insights that added immense value to our project, on your needs an Based on your needs, we devise. The support team is exceptional! They've been responsive and helpful at every step.”`,
  image: TesBigImg,
}));

const Testimonial = () => {
  const [nav1, setNav1] = useState<Slider>();
  const [nav2, setNav2] = useState<Slider>();

  const sliderRef1 = useRef<Slider | null>(null);
  const sliderRef2 = useRef<Slider | null>(null);

  useEffect(() => {
    setNav1(sliderRef1.current!);
    setNav2(sliderRef2.current!);
  }, []);

  const setting1 = {
    slidesToShow: 5,
    slidesToScroll: 1,
    arrows: false,
    loop: true,
    focusOnSelect: true,
    responsive: [
      {
        breakpoint: 769,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: '40px',
          slidesToShow: 3,
        },
      },
      {
        breakpoint: 480,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: '40px',
          slidesToShow: 2,
        },
      },
    ],
  };

  const setting2 = {
    margin: '30',
    slidesToShow: 1,
    arrows: false,
    centerMode: true,
    loop: true,
    draggable: true,
    fade: true,
    responsive: [
      {
        breakpoint: 769,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: '40px',
          slidesToShow: 1,
        },
      },
      {
        breakpoint: 480,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: '40px',
          slidesToShow: 1,
        },
      },
    ],
  };

  return (
    <>
      <div className="testimonial-area pb120" id="tes">
        <Container>
          <Row>
            <Col lg={6} className="m-auto text-center">
              <div className="headding1">
                <span className="span" data-aos="fade-up" data-aos-duration="800">
                  <img src={headings} alt="" /> Client Testimonials
                </span>
                <h2 data-aos="fade-up" data-aos-duration="1000">
                  Loved by industry <span className="after">leaders</span>
                </h2>
              </div>
            </Col>
          </Row>

          <div className="space60" /> 
          <Row>
            <Col lg={12}>
              <div className="testimonial-slider-all" data-aos="fade-up" data-aos-duration="1100">
                <div className="testimonial-single-slider">
                  <Slider
                    ref={sliderRef1}
                    asNavFor={nav2}
                    {...setting1}
                    className="tes1-brads-slider"
                  >
                    {testimonial1.map((item, idx) => (
                      <div key={idx} className="single">
                        <img src={item.image} alt="" />
                      </div>
                    ))}
                  </Slider>
                  <Slider
                    ref={sliderRef2}
                    asNavFor={nav1}
                    {...setting2}
                    className="tes1-big-slider"
                  >
                    {testimonials.map(item => (
                      <div className="single-slider" key={item.id}>
                        <Row>
                          <Col lg={8}>
                            <ul className="stars">
                              {[...Array(5)].map((_, i) => (
                                <li key={i}>
                                  <FaStar />
                                </li>
                              ))}
                            </ul>
                            <p className="pera">{item.message}</p>
                            <div className="bottom-headding">
                              <h4>
                                <Link to="">
                                  {item.name}/{item.role}, {item.company}
                                </Link>
                              </h4>
                              <Link className="ancor" to="/testimonial">
                                Read More Testimonials Feedback
                              </Link>
                            </div>
                          </Col>
                          <Col lg={4}>
                            <div className="image">
                              <img src={item.image} alt={item.name} />
                            </div>
                          </Col>
                        </Row>
                      </div>
                    ))}
                  </Slider>

                  <div className="testimonial-arrows">
                    <button
                      className="testimonial-prev-arrow"
                      onClick={() => sliderRef2.current?.slickPrev()}
                    >
                      <FaArrowLeft />
                    </button>
                    <button
                      className="testimonial-next-arrow"
                      onClick={() => sliderRef2.current?.slickNext()}
                    >
                      <FaArrowRight />
                    </button>
                  </div>
                </div>
              </div>
            </Col>
          </Row>
        </Container>
      </div>
    </>
  );
};

export default Testimonial;
